// The console talks to one of two backends with the same shape:
//   server  – `npm start`: the authority runs in Node, events stream over SSE
//   local   – no server reachable (e.g. the hosted demo): the same authority code
//             runs in this tab, with real Ed25519 keys generated by WebCrypto

import { DemoWorld } from '../core/demo-world.js';
import { Signer, verifySealed } from '../core/keys.js';
import { verifyConsistency } from '../core/merkle.js';

// An independent witness living in this tab. It co-signs a checkpoint only if the log
// it saw last time is a prefix of the log now, so the authority cannot rewrite history
// without the witness noticing.
const witness = { signer: null, last: null, name: 'Browser witness' };
async function observe(backend) {
  witness.signer ||= await Signer.generate();
  const cp = await backend.rawCheckpoint();
  if (!(await verifySealed(cp, cp.authority))) throw new Error('checkpoint signature is invalid');
  let proof = [];
  if (witness.last && witness.last.authority === cp.authority && witness.last.size > 0) {
    if (cp.size < witness.last.size) throw new Error('the log shrank: refusing to co-sign');
    proof = (await backend.consistency(witness.last.size, cp.size)).proof;
    if (!(await verifyConsistency(witness.last.size, cp.size, witness.last.root, cp.root, proof))) throw new Error('the log was rewritten: refusing to co-sign');
  }
  const prev = witness.last;
  witness.last = cp;
  const cos = await witness.signer.seal({ type: 'WitnessCosignature', witness: witness.signer.did, name: witness.name, checkpoint: cp });
  await backend.recordWitness(cos);
  return { checkpoint: cp, previous: prev, proof, witness: witness.signer.did };
}

export async function connect() {
  const forceLocal = new URLSearchParams(location.search).has('local');
  if (!forceLocal && location.protocol.startsWith('http')) {
    try {
      const res = await fetch('api/health', { cache: 'no-store' });
      if (res.ok && res.headers.get('content-type')?.includes('json')) {
        const body = await res.json();
        if (body.mode === 'server') return new RemoteBackend({ rpId: location.hostname, origins: [location.origin] });
      }
    } catch { /* fall back to in-tab authority */ }
  }
  return LocalBackend.create();
}

// Passkeys bind to the page's own origin. Sandboxed frames report an opaque origin,
// in which case the virtual authenticator signs for a stand-in site instead.
const opaque = !location.hostname || location.origin === 'null';
export const WEBAUTHN = opaque
  ? { rpId: 'agentid.demo', origins: ['https://agentid.demo'] }
  : { rpId: location.hostname, origins: [location.origin] };
const newWorld = () => DemoWorld.create({ authorityOptions: { webauthn: WEBAUTHN } });

class LocalBackend {
  mode = 'local';
  static async create() {
    const b = new LocalBackend();
    b.world = await newWorld();
    b.listeners = new Set();
    b.unhook = b.world.on((ev) => b.listeners.forEach((fn) => fn(ev)));
    return b;
  }
  on(fn) { this.listeners.add(fn); }
  snapshot() { return this.world.snapshot(); }
  tick() { return this.world.tick(); }
  attack(kind) { return this.world.attack(kind); }
  approve(id, decision, key) { return this.world.approve(id, decision, { key }); }
  revoke(target, reason) { return this.world.revoke(target, reason); }
  delegate(spec) { return this.world.delegate(spec); }
  ledger(opts) { return this.world.ledger(opts); }
  verifyLedger() { return this.world.verifyLedger(); }
  freeze(frozen, reason) { return this.world.freeze(frozen, reason); }
  rotateAgent(agent) { return this.world.rotateAgent(agent); }
  rotateKey() { return this.world.rotateOperationalKey(); }
  recoverRoot() { return this.world.recoverRoot(); }
  passkeyChallenge() { return this.world.passkeyChallenge(); }
  enrollPasskey(body) { return this.world.enrollPasskey(body); }
  passkeyApprovalChallenge(id, decision) { return this.world.passkeyApprovalChallenge(id, decision); }
  approveWithPasskey(id, decision, assertion) { return this.world.approveWithPasskey(id, decision, assertion); }
  federation(kind) { return this.world.federation(kind); }
  mcp(kind) { return this.world.mcp(kind); }
  oauth(svid) { return this.world.oauth({ svid }); }
  credential(agent) { return this.world.credential(agent); }
  async checkpoint() {
    const A = this.world.authority;
    const cp = await A.checkpoint();
    return { checkpoint: cp, inclusion: cp.size ? await A.inclusionProof(cp.size - 1) : null };
  }
  webauthn() { return this.world.authority.webauthn; }
  rawCheckpoint() { return this.world.authority.checkpoint(); }
  consistency(first, second) { return this.world.authority.consistencyProof(first, second); }
  recordWitness(c) { return this.world.authority.recordWitness(c); }
  witness() { return observe(this); }
  async reset() {
    witness.last = null;
    this.unhook?.();
    this.world = await newWorld();
    this.unhook = this.world.on((ev) => this.listeners.forEach((fn) => fn(ev)));
    this.listeners.forEach((fn) => fn({ type: 'reset', data: {} }));
  }
}

class RemoteBackend {
  mode = 'server';
  constructor(webauthnConfig) {
    this.webauthnConfig = webauthnConfig;
    this.listeners = new Set();
    const es = new EventSource('api/events');
    for (const type of ['decision', 'approval', 'revoked', 'registry', 'ledger', 'reset', 'freeze', 'federation', 'witness']) {
      es.addEventListener(type, (e) => {
        const data = JSON.parse(e.data || '{}');
        this.listeners.forEach((fn) => fn({ type, data }));
      });
    }
  }
  async #call(method, path, body) {
    const res = await fetch(path, { method, headers: body ? { 'content-type': 'application/json' } : {}, body: body ? JSON.stringify(body) : undefined });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'request failed');
    return data;
  }
  on(fn) { this.listeners.add(fn); }
  snapshot() { return this.#call('GET', 'api/snapshot'); }
  tick() { return this.#call('POST', 'api/demo/tick', {}); }
  attack(kind) { return this.#call('POST', 'api/demo/attack', { kind }); }
  approve(id, decision, key) { return this.#call('POST', 'api/demo/approve', { id, decision, key }); }
  freeze(frozen, reason) { return this.#call('POST', 'api/demo/freeze', { frozen, reason }); }
  rotateAgent(agent) { return this.#call('POST', 'api/demo/rotate-agent', { agent }); }
  rotateKey() { return this.#call('POST', 'api/demo/rotate-key', {}); }
  recoverRoot() { return this.#call('POST', 'api/demo/recover-root', {}); }
  passkeyChallenge() { return this.#call('POST', 'api/demo/passkey/challenge', {}); }
  enrollPasskey(body) { return this.#call('POST', 'api/demo/passkey/enroll', body || {}); }
  passkeyApprovalChallenge(id, decision) { return this.#call('POST', 'api/demo/passkey/approval-challenge', { id, decision }); }
  approveWithPasskey(id, decision, assertion) { return this.#call('POST', 'api/demo/passkey/approve', { id, decision, assertion }); }
  federation(kind) { return this.#call('POST', 'api/demo/federation', { kind }); }
  mcp(kind) { return this.#call('POST', 'api/demo/mcp', { kind }); }
  oauth(svid) { return this.#call('POST', 'api/demo/oauth', { svid }); }
  credential(agent) { return this.#call('POST', 'api/demo/credential', { agent }); }
  checkpoint() { return this.#call('GET', 'api/checkpoint'); }
  webauthn() { return this.webauthnConfig; }
  rawCheckpoint() { return this.#call('GET', 'v1/checkpoint'); }
  consistency(first, second) { return this.#call('GET', `v1/proofs/consistency?first=${first}&second=${second}`); }
  recordWitness(c) { return this.#call('POST', 'v1/witness', c); }
  witness() { return observe(this); }
  revoke(target, reason) { return this.#call('POST', 'api/demo/revoke', { target, reason }); }
  delegate(spec) { return this.#call('POST', 'api/demo/delegate', spec); }
  ledger({ from = 0, limit = 200 } = {}) { return this.#call('GET', `api/ledger?from=${from}&limit=${limit}`); }
  verifyLedger() { return this.#call('GET', 'api/ledger/verify'); }
  reset() { witness.last = null; return this.#call('POST', 'api/demo/reset', {}); }
}
